func BenchmarkEncodeDecodeBaseRange(b *testing.B) {
	seed := fullyPopulatedBaseRange
	w := orc.NewWriter(0)
	r := orc.NewReader(nil)
	for b.Loop() {
		w.Reset()
		if err := seed.EncodeOrc(w); err != nil {
			b.Fatal(err)
		}
		var decoded v7.BaseRange
		r.ResetBytes(w.Bytes())
		if err := decoded.DecodeOrc(r); err != nil {
			b.Fatal(err)
		}
	}
}

